script:
class Component extends DCLogic {
  constructor(props) { super(props); this.state = { f: 'all', m: '', cur: 0, gMode: 'project', gProj: '', gTopic: '', gFmt: 'post', gLang: 'Русский', gErr: false, gDone: false, shareTitle: '' }; }

  _y(e) { try { const m = document.querySelector('main.kab__main'); return Math.round(e.currentTarget.getBoundingClientRect().top - m.getBoundingClientRect().top); } catch (x) { return 120; } }
  say(msg, e) { const y = this._y(e); this.setState({ toast: msg, toastY: Math.max(8, y + ((e && e.currentTarget && e.currentTarget.offsetHeight) || 40) + 8) }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); }
  openM(name, e, extra) { const y = this._y(e); this.setState(Object.assign({ m: name, mTop: Math.max(16, y - 40) }, extra || {})); }
  closeM() { this.setState({ m: '' }); }
  baseVals() {
    const S = this.state;
    return { toastOn: !!S.toast, toast: S.toast || '', toastStyle: 'top:' + (S.toastY || 80) + 'px;width:max-content;max-width:min(420px,calc(100% - 32px))', mOn: !!S.m, ovlStyle: 'padding-top:' + (S.mTop || 24) + 'px',
      closeOvl: (e) => { if (e.target === e.currentTarget) this.closeM(); }, closeBtn: () => this.closeM(),
      helpOpen: (e) => this.openM('help', e), m_help: S.m === 'help' };
  }

  renderVals() {
    const S = this.state;
    const ALL = [
      { k: 'video', kind: 'Ролик', title: 'Creek Residence: квартира у воды в Дубае', desc: 'Вертикальный ролик 40 секунд, без логотипа. Подпись и ссылка уже внутри.', url: 'housebook.global/p/creek-residence?cl=PRG7K2' },
      { k: 'video', kind: 'Ролик', title: 'Батуми: что можно купить за 95 000 USD', desc: 'Три объекта у моря с ценами. Озвучено с помощью ИИ.', url: 'housebook.global/p/batumi-95?cl=PRG7K2' },
      { k: 'story', kind: 'Сторис', title: '5 вопросов перед покупкой за рубежом', desc: 'Пять картинок для Instagram.', url: 'housebook.global/p/5-voprosov?cl=PRG7K2' },
      { k: 'story', kind: 'Сторис', title: 'Вид на жительство через квартиру в Турции', desc: 'Короткая серия о том, что нужно и сколько это занимает.', url: 'housebook.global/p/turkey-vnzh?cl=PRG7K2' },
      { k: 'story', kind: 'Сторис', title: 'Лимассол: дома с садом для семьи', desc: 'Три дома с фото и ценами. Подходит для клиентов с детьми.', url: 'housebook.global/p/limassol-doma?cl=PRG7K2' },
      { k: 'text', kind: 'Статья', title: 'Как купить квартиру в Дубае, не приезжая', desc: 'Что сделать по шагам и в каком порядке. Читается за 5 минут.', url: 'housebook.global/blog/dubai-udalenno?cl=PRG7K2' },
      { k: 'text', kind: 'Статья', title: 'Налоги и расходы при покупке в Грузии', desc: 'Что платит покупатель, а что продавец. Простыми словами.', url: 'housebook.global/blog/georgia-rashody?cl=PRG7K2' },
      { k: 'pdf', kind: 'PDF-гид', title: 'Гид по покупке в ОАЭ для начинающих', desc: 'Восемь страниц для клиента. Ваш контакт и ссылка на последней странице.', url: 'housebook.global/guide/uae?cl=PRG7K2' }];
    const PVC = { video: 'mcard__pv mcard__pv--video', story: 'mcard__pv mcard__pv--story', text: 'mcard__pv mcard__pv--text', pdf: 'mcard__pv mcard__pv--text' };
    const FIL = [['all', 'Все'], ['story', 'Сторис'], ['video', 'Ролики'], ['text', 'Статьи'], ['pdf', 'PDF-гиды']];
    const pills = FIL.map(([k, t]) => ({ t, n: k === 'all' ? ALL.length : ALL.filter((x) => x.k === k).length, on: S.f === k, pick: () => this.setState({ f: k }) }));
    const items = ALL.map((x, i) => Object.assign({}, x, { pvCls: PVC[x.k], i })).filter((x) => S.f === 'all' || x.k === S.f).map((x) => Object.assign({}, x, {
      share: (e) => this.openM('share', e, { shareTitle: x.title }), copy: (e) => this.say('Текст скопирован. Ссылка уже внутри', e), open: (e) => this.openM('prev', e, { cur: x.i }) }));
    const cur = Object.assign({}, ALL[S.cur], { pvCls: PVC[ALL[S.cur].k] });
    const PRJ = ['Creek Residence, Дубай', 'Marina Heights, Дубай', 'Батуми, у моря'];
    const mk = (arr, val, key) => arr.map((t) => ({ t, on: S[key] === t, pick: () => this.setState({ [key]: t, gErr: false }) }));
    const gModes = [['project', 'О проекте'], ['topic', 'Своя тема'], ['video', 'Видео']].map(([k, t]) => ({ t, on: S.gMode === k, pick: () => this.setState({ gMode: k, gErr: false }) }));
    const noProj = S.gErr && S.gMode !== 'topic' && !S.gProj, noTopic = S.gErr && S.gMode === 'topic' && !S.gTopic.trim();
    const what = S.gMode === 'topic' ? S.gTopic.trim() : S.gProj;
    const slides = [{ h: 'Слайд 1. Заголовок', p: what || 'Тема' }, { h: 'Слайд 2. Главное о проекте', p: 'Цена, срок сдачи, район.' }, { h: 'Слайд 3. Фото', p: 'Подобраны из каталога.' }, { h: 'Слайд 4. Ваш контакт', p: 'Имя и ссылка Илья Перагов, PRG7K2.' }];
    return Object.assign(this.baseVals(), { pills, items, cur, curCopy: (e) => this.say('Текст скопирован. Ссылка уже внутри', e), curDl: (e) => this.say('Материал сохранён', e), curShare: (e) => this.openM('share', e, { shareTitle: cur.title }),
      m_gen: S.m === 'gen', m_prev: S.m === 'prev', m_share: S.m === 'share', shareTitle: S.shareTitle,
      gForm: !S.gDone, gDone: S.gDone, gModes, gIsProj: S.gMode !== 'topic', gIsTopic: S.gMode === 'topic', gProjs: mk(PRJ, S.gProj, 'gProj'),
      gFmts: mk(['Пост 4:5', 'Сторис 9:16'], S.gFmt, 'gFmt').map((o) => Object.assign(o, { on: S.gFmt === o.t })), gLangs: mk(['Русский', 'English', 'Deutsch', 'Italiano', 'Українська', 'Français'], S.gLang, 'gLang'),
      gTopic: S.gTopic, gSetTopic: (e) => this.setState({ gTopic: e.target.value, gErr: false }), gErrCls: (noProj || noTopic) ? 'is-err' : '', gErrProj: noProj ? 'Выберите проект' : '', gErrTopic: noTopic ? 'Напишите тему' : '',
      gMake: (e) => { if (e && e.preventDefault) e.preventDefault(); if (S.gMode === 'topic' ? !S.gTopic.trim() : !S.gProj) { this.setState({ gErr: true }); return; } this.setState({ gDone: true }); },
      gResTitle: S.gMode === 'video' ? 'Ролик готов' : 'Карусель готова', gSlides: slides, gDl: (e) => this.say('Материал сохранён', e), gShare: (e) => this.openM('share', e, { shareTitle: what || 'Новый материал' }), gAgain: () => this.setState({ gDone: false }),
      genProject: (e) => this.openM('gen', e, { gMode: 'project', gDone: false, gErr: false }), genTopic: (e) => this.openM('gen', e, { gMode: 'topic', gDone: false, gErr: false }), genVideo: (e) => this.openM('gen', e, { gMode: 'video', gDone: false, gErr: false }),
      sayWa: (e) => this.say('В кабинете откроется WhatsApp', e), sayTg: (e) => this.say('В кабинете откроется Telegram', e), sayMail: (e) => this.say('В кабинете откроется письмо', e), sayCopy: (e) => this.say('Ссылка скопирована', e) });
  }
}
